INSERT INTO case_study_images (id, case_study_id, media_id, role, position, caption, alt_text, object_position, created_at, updated_at) VALUES ('img_marlow_gallery_a_0', 'case_marlow', 'media_cases-marlow', 'gallery_a', 0, 'The wordmark, cut like a dovetail joint', '', '20% 30%', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z');
