INSERT INTO blog_categories (id, slug, title, status, position, created_at, updated_at, published_at) VALUES ('cat_brand', 'brand', 'Brand', 'published', 0, '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z');
