INSERT INTO blog_categories (id, slug, title, status, position, created_at, updated_at, published_at) VALUES ('cat_process', 'process', 'Process', 'published', 4, '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z');
INSERT INTO blog_posts (id, slug, title, status, category_id, meta_title, meta_description, excerpt, featured, lead, body_json, outro_json, related_json, read_minutes, author_name, author_image_id, cover_image_id, cover_alt, created_at, updated_at, published_at) VALUES ('post_design-systems-that-survive', 'design-systems-that-survive', 'Design systems that survive contact with a roadmap', 'published', 'cat_product', 'Design systems that survive contact with a roadmap — Visuolab', 'Most design systems die in month four. Here is what the ones that last have in common — and the three things we now build on day one.', 'Most design systems die in month four. Here is what the ones that last have in common — and the three things we now build on day one.', 1, 'A design system is not a component library. It is an agreement between designers and engineers about how decisions get made — and agreements need maintenance.', '[{"type":"heading","text":"Start with the ten screens you actually have"},{"type":"paragraph","text":"Systems fail when they are designed in the abstract. Build the components the current product needs, in the order it needs them, and let the library grow out of real screens instead of a hypothetical catalogue."},{"type":"heading","text":"Tokens before components"},{"type":"paragraph","text":"Colour, type, spacing and motion as named values, shipped to code before anyone draws a button. Every component you build afterwards inherits the decisions instead of re-litigating them."},{"type":"heading","text":"One owner, one hour a week"},{"type":"paragraph","text":"The systems that survive have a name next to them. An hour a week of triage — what got added, what drifted, what should be deleted — is the difference between a system and a graveyard."},{"type":"heading","text":"Motion is part of the system"},{"type":"paragraph","text":"Durations and easings belong in the token set. Without them, every team invents its own timing and the product feels like four different products."}]', '{"before":"Working on something like this?","linkText":"Tell us about it","href":"#contact","after":" — we answer within a day."}', '["what-a-rebrand-actually-costs","motion-that-earns-its-place"]', 7, 'Jordan Ellis', 'media_people-jordan', 'media_covers-design-systems-that-survive', '', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', '2026-09-12T00:00:00.000Z');
INSERT INTO blog_posts (id, slug, title, status, category_id, meta_title, meta_description, excerpt, featured, lead, body_json, outro_json, related_json, read_minutes, author_name, author_image_id, cover_image_id, cover_alt, created_at, updated_at, published_at) VALUES ('post_what-a-rebrand-actually-costs', 'what-a-rebrand-actually-costs', 'What a rebrand actually costs (and what you get for it)', 'published', 'cat_brand', 'What a rebrand actually costs (and what you get for it) — Visuolab', 'Ranges, line items and the three decisions that move the number more than anything else. No discovery call required.', NULL, 0, 'Every agency answers this with "it depends". That is true and useless, so here is the shape of the number and what actually moves it.', '[{"type":"heading","text":"Scope beats seniority"},{"type":"paragraph","text":"A wordmark for a five-person startup and a wordmark for a company with three showrooms and a van fleet are the same craft and very different projects. What changes the price is the number of surfaces the identity has to live on."},{"type":"heading","text":"Research is the optional half"},{"type":"paragraph","text":"Positioning work, interviews and market audits can double a budget. Sometimes they are essential; sometimes the founders already know the answer and need someone to draw it well."},{"type":"heading","text":"Rollout is where budgets go missing"},{"type":"paragraph","text":"The identity is a few weeks. Applying it to packaging, signage, templates and a site is where the rest of the money and time goes — plan it as its own phase."},{"type":"heading","text":"What we quote"},{"type":"paragraph","text":"A fixed price per scope, agreed before we start. If the scope changes, the number changes and we say so that week — never at the end."}]', '{"before":"Working on something like this?","linkText":"Tell us about it","href":"#contact","after":" — we answer within a day."}', '["motion-that-earns-its-place","the-brief-that-writes-itself"]', 6, 'Harriet Marlow', 'media_people-harriet', 'media_covers-what-a-rebrand-actually-costs', '', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', '2026-08-28T00:00:00.000Z');
INSERT INTO blog_posts (id, slug, title, status, category_id, meta_title, meta_description, excerpt, featured, lead, body_json, outro_json, related_json, read_minutes, author_name, author_image_id, cover_image_id, cover_alt, created_at, updated_at, published_at) VALUES ('post_motion-that-earns-its-place', 'motion-that-earns-its-place', 'Motion that earns its place', 'published', 'cat_motion', 'Motion that earns its place — Visuolab', 'A simple test for whether an animation should ship: does it explain, guide or delight? If it does none of the three, cut it.', NULL, 0, 'Motion is the easiest thing to add and the hardest thing to justify. We run every animation through the same three questions before it ships.', '[{"type":"heading","text":"Does it explain?"},{"type":"paragraph","text":"The best animations teach: where a panel came from, what a swipe will do, how yield accrues. If an animation makes a mechanism legible, it has earned its place."},{"type":"heading","text":"Does it guide?"},{"type":"paragraph","text":"Motion directs attention. A state change that animates tells the user their action worked; a list that staggers tells them where to start reading."},{"type":"heading","text":"Does it delight — once?"},{"type":"paragraph","text":"A moment of charm is worth it the first time and irritating the fiftieth. Delight belongs in rare moments: onboarding, empty states, a successful payment."},{"type":"heading","text":"The durations we default to"},{"type":"paragraph","text":"120ms for state feedback, 240–320ms for transitions, 600ms+ only for storytelling. Ease-out for things entering, ease-in for things leaving."}]', '{"before":"Working on something like this?","linkText":"Tell us about it","href":"#contact","after":" — we answer within a day."}', '["the-brief-that-writes-itself","webflow-or-next-js"]', 5, 'Ingrid Halvorsen', 'media_people-ingrid', 'media_covers-motion-that-earns-its-place', '', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', '2026-08-14T00:00:00.000Z');
INSERT INTO blog_posts (id, slug, title, status, category_id, meta_title, meta_description, excerpt, featured, lead, body_json, outro_json, related_json, read_minutes, author_name, author_image_id, cover_image_id, cover_alt, created_at, updated_at, published_at) VALUES ('post_the-brief-that-writes-itself', 'the-brief-that-writes-itself', 'The brief that writes itself', 'published', 'cat_process', 'The brief that writes itself — Visuolab', 'Five questions we ask before every project. If you can answer them, you probably do not need an agency to find the problem — just to solve it.', NULL, 0, 'Most projects that go wrong went wrong in the brief. These five questions surface the disagreement early, while it is still cheap.', '[{"type":"heading","text":"What has to be true in twelve months?"},{"type":"paragraph","text":"Not the deliverable — the outcome. If the answer is \"more qualified leads\", the project is different from one where the answer is \"we can raise a Series B\"."},{"type":"heading","text":"Who decides?"},{"type":"paragraph","text":"Name the person who can say yes. Projects with three equal decision-makers take twice as long and end up designed by committee."},{"type":"heading","text":"What is already working?"},{"type":"paragraph","text":"There is always something. Knowing what not to touch protects the equity you have already built."},{"type":"heading","text":"What is the real deadline?"},{"type":"paragraph","text":"A board meeting, a trade show, a launch window. Real dates change the plan; invented ones just add stress."},{"type":"heading","text":"What does failure look like?"},{"type":"paragraph","text":"The clearest question of the five. Teams who can describe failure precisely are the ones who describe success precisely too."}]', '{"before":"Working on something like this?","linkText":"Tell us about it","href":"#contact","after":" — we answer within a day."}', '["webflow-or-next-js","designing-for-trust-in-fintech"]', 4, 'Jordan Ellis', 'media_people-jordan', 'media_covers-the-brief-that-writes-itself', '', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', '2026-07-30T00:00:00.000Z');
INSERT INTO blog_posts (id, slug, title, status, category_id, meta_title, meta_description, excerpt, featured, lead, body_json, outro_json, related_json, read_minutes, author_name, author_image_id, cover_image_id, cover_alt, created_at, updated_at, published_at) VALUES ('post_webflow-or-next-js', 'webflow-or-next-js', 'Webflow or Next.js? A decision tree we actually use', 'published', 'cat_web', 'Webflow or Next.js? A decision tree we actually use — Visuolab', 'Marketing site, app-adjacent, or somewhere in between — here is how we choose, and when we have been wrong.', NULL, 0, 'This is a question about who will maintain the site, not about which technology is better.', '[{"type":"heading","text":"Who edits it, and how often?"},{"type":"paragraph","text":"If marketing needs to ship a page on a Tuesday without an engineer, Webflow wins almost every time. If content changes rarely and lives next to the product, Next.js is simpler."},{"type":"heading","text":"How much of it is product?"},{"type":"paragraph","text":"Anything that reads live application state — dashboards, logged-in views, pricing that depends on the user — belongs in the app codebase."},{"type":"heading","text":"What does the team already run?"},{"type":"paragraph","text":"A four-person engineering team already deploying Next.js will maintain a Next.js site happily. The same team will resent a CMS they did not choose."},{"type":"heading","text":"Where we have been wrong"},{"type":"paragraph","text":"Twice we have built in Next.js for teams who then wanted daily content changes. Both migrated to Webflow within a year — the tell was a marketing hire we did not account for."}]', '{"before":"Working on something like this?","linkText":"Tell us about it","href":"#contact","after":" — we answer within a day."}', '["designing-for-trust-in-fintech","design-systems-that-survive"]', 6, 'Ingrid Halvorsen', 'media_people-ingrid', 'media_covers-webflow-or-next-js', '', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', '2026-07-16T00:00:00.000Z');
INSERT INTO blog_posts (id, slug, title, status, category_id, meta_title, meta_description, excerpt, featured, lead, body_json, outro_json, related_json, read_minutes, author_name, author_image_id, cover_image_id, cover_alt, created_at, updated_at, published_at) VALUES ('post_designing-for-trust-in-fintech', 'designing-for-trust-in-fintech', 'Designing for trust in fintech', 'published', 'cat_product', 'Designing for trust in fintech — Visuolab', 'Showing fees before the wallet prompt lost us nothing and gained 44% more connections. A few more counter-intuitive results.', NULL, 0, 'In finance, the fastest path to a conversion is usually not the shortest one. Every shortcut you take is a question the user answers with suspicion instead.', '[{"type":"heading","text":"Show the cost before you ask for the commitment"},{"type":"paragraph","text":"Fees, risks and limits up front. Every time we have tested this, completion went up — the people who leave were going to churn at the first statement anyway."},{"type":"heading","text":"Plain language beats precise language"},{"type":"paragraph","text":"\"You keep 97% of what you earn\" outperforms a technically perfect fee table. Put the table underneath for the people who want it."},{"type":"heading","text":"Let people undo things"},{"type":"paragraph","text":"A visible cancel, a clear refund path and a payment that can be edited for sixty seconds do more for trust than any badge or seal."},{"type":"heading","text":"Identity checks at the moment of need"},{"type":"paragraph","text":"Nobody wants to photograph a passport before they have seen the product. Move verification to the first transfer and funded accounts double."}]', '{"before":"Working on something like this?","linkText":"Tell us about it","href":"#contact","after":" — we answer within a day."}', '["design-systems-that-survive","what-a-rebrand-actually-costs"]', 8, 'Aiko Sato', 'media_people-aiko', 'media_covers-designing-for-trust-in-fintech', '', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', '2026-07-02T00:00:00.000Z');
