INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_home_services', 'home.services', 'Home: services section', 'published', '{"label":"Services","title":"Brand, product and web, <em>designed as one</em>","lead":"One tight team carries the idea from workshop to launch, so it looks and feels the same on every surface it touches.","columns":[{"title":"Branding","links":["Brand strategy","Naming","Visual identity","Art direction","Brand guidelines"]},{"title":"Product design","links":["UX research","UI design","Mobile app design","Design systems","Prototyping"]},{"title":"Web & motion","links":["Web design","Webflow development","Next.js sites","Motion design","3D & illustration"]}],"bookBar":{"name":"Jordan Ellis","role":"Founder & Creative Director","text":"Grow your brand with a team that has shipped 140+ products — and stays until yours is live.","cta":"Book a call"}}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
