INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_home_industries', 'home.industries', 'Home: industries', 'published', '{"label":"Industries we serve","title":"Deep in the markets that <em>move fastest</em>","lead":"We''ve shipped brands, products and sites across 30+ industries. These are the four we know best — where our playbooks are sharpest and the results come quickest.","items":[{"icon":"industry-1","title":"SaaS & B2B","text":"Positioning, product UI and marketing sites for software teams that need to explain something complex in a single scroll."},{"icon":"industry-2","title":"Fintech","text":"Onboarding, dashboards and trust-building brand work for money apps, where every screen has to feel safe before it feels clever."},{"icon":"industry-3","title":"Health & wellness","text":"Calm, accessible product design and packaging for care, skincare and wellbeing brands that people trust with their bodies."},{"icon":"industry-4","title":"E-commerce & retail","text":"Storefronts, packaging and campaigns built to convert on the shelf and in the feed — and to keep customers coming back."}]}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_home_process', 'home.process', 'Home: how we work', 'published', '{"label":"How we work","title":"A process built for <em>momentum</em>","lead":"Four steps, one team, no big reveals. You see the work as it happens and decide on real things — not slide decks.","facts":["8–14 week engagements","Weekly working sessions","One shared design file"],"cta":"Book an intro call","steps":[{"label":"Discover","title":"Understand <em>before</em> we design","text":"Stakeholder interviews, user research and a hard look at what exists today. We leave with a shared definition of the problem worth solving.","outputs":["Research readout","Audit","Success metrics"],"when":"1–2 weeks"},{"label":"Define","title":"Agree on the <em>destination</em>","text":"Positioning, design principles and a prioritised scope — sketched as quick concepts so decisions get made on something you can see.","outputs":["Creative direction","Concepts","Roadmap"],"when":"1–2 weeks"},{"label":"Design","title":"Craft, <em>in the open</em>","text":"Brand, interface and motion take shape in one shared file you can open any time. Weekly sessions replace presentations, so nothing lands as a surprise.","outputs":["Identity / UI","Prototype","Design system"],"when":"4–8 weeks"},{"label":"Deliver","title":"Ship it, then <em>keep going</em>","text":"We build it ourselves or pair with your engineers through launch — then stay on to measure what happened and iterate on what''s next.","outputs":["Build or handoff","Launch support","Retainer"],"when":"2–4 weeks"}]}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_about_principles', 'about.principles', 'About: principles', 'published', '{"label":"How we think","title":"The principles <em>behind</em> the work","lead":"Five things we won''t compromise on, whatever the brief.","items":[{"num":"01","title":"Craft over volume","text":"We take on a handful of projects at a time so senior people stay on yours from kickoff to launch."},{"num":"02","title":"One idea, every surface","text":"Brand, product and web are designed by the same hands, so the story doesn''t drift between them."},{"num":"03","title":"Motion is meaning","text":"Animation earns its place by explaining, guiding or delighting — never by default."},{"num":"04","title":"Decide on real things","text":"Concepts, prototypes and working files replace slide decks. You see the work as it happens."},{"num":"05","title":"Ship, then keep going","text":"Launch is a milestone, not the finish line. We stay to measure, learn and iterate."}]}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_about_mission_vision', 'about.mission_vision', 'About: mission and vision', 'published', '[{"tag":"The image of the future","title":"Mission","text":"To design brands, products and websites that carry one idea faithfully from the first sketch to the last screen — with small senior teams, honest advice, and the patience to stay past launch and keep improving what we shipped."},{"tag":"Our ambition","title":"Vision","text":"To be the studio founders call first — trusted with the work that defines a company, still around when it''s time to evolve it, and a place where every launch raises the bar for the next one."}]', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_about_milestones', 'about.milestones', 'About: our story timeline', 'published', '{"label":"Our story","title":"From <em>two laptops</em> in Lisbon to a studio on four continents","items":[{"year":"2017","title":"Two designers, one desk","text":"Visuolab starts as a two-person brand studio in a shared Lisbon workspace. First client: a seed-stage fintech that is still with us."},{"year":"2019","title":"Product joins brand","text":"The first product-design retainer turns a brand shop into a full design studio. Five people, first Clutch reviews."},{"year":"2021","title":"Remote by design","text":"We go fully distributed, with teammates in Toronto and Singapore, and become a Webflow professional partner."},{"year":"2023","title":"The hundredth launch","text":"Design engineering and motion become core disciplines. First Awwwards Site of the Day."},{"year":"2026","title":"Today","text":"Fourteen people across four continents, 140+ launches — and still no account managers between you and the work."}]}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_about_manifesto', 'about.manifesto', 'About: manifesto', 'published', '{"label":"Why Visuolab exists","text":"We started Visuolab because we were tired of watching <em>good ideas</em> get diluted between the deck, the design and the build. So we built a studio where <em>the same people</em> carry an idea from the first sketch to the last screen — and stay accountable for how it performs. Small on purpose. Senior by default. <em>Honest</em> about what will and won''t move the needle."}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_about_offices', 'about.offices', 'About: where we work', 'published', '{"label":"Where we work","title":"Four continents. <em>One working day.</em>","lead":"Lisbon is home. Toronto, Singapore and Sydney keep the sun up on your project — whatever your timezone, there are at least four shared hours a day and a designer who''s awake.","items":[{"tz":"Europe/Lisbon","city":"Lisbon","country":"Portugal · HQ","flag":"Portugal"},{"tz":"America/Toronto","city":"Toronto","country":"Canada","flag":"Canada"},{"tz":"Asia/Singapore","city":"Singapore","country":"Singapore","flag":"Singapore"},{"tz":"Australia/Sydney","city":"Sydney","country":"Australia","flag":"Australia"}]}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_about_faq', 'about.faq', 'About: frequently asked questions', 'published', '{"label":"FAQ","title":"Questions <em>we get</em> a lot","lead":"Can''t find yours? Write to us — a real person answers within a day.","cta":"Ask us anything","items":[{"id":"qa-1","q":"What does a typical engagement look like?","a":"Most projects run six to fourteen weeks: a brand or product sprint first, then web design and build. Teams that want a design partner on call work with us on a monthly retainer instead."},{"id":"qa-2","q":"How do you price?","a":"A fixed price per scope for defined projects and a flat monthly rate for retainers. You''ll have a number before we start, and it doesn''t move unless the scope does."},{"id":"qa-3","q":"Who will actually work on our project?","a":"The people you meet in the first call. A lead designer, a design engineer and a strategist stay on your project from kickoff to launch — there''s no hand-off to a junior team."},{"id":"qa-4","q":"Do you work with early-stage startups?","a":"Yes — about a third of our launches are pre-Series A. We''ll tell you plainly what''s worth building now and what can wait until you have users."},{"id":"qa-5","q":"Do you build what you design?","a":"Yes. Webflow for marketing sites, Next.js when the product needs it. Design and build sit in the same room, so nothing gets lost between them."},{"id":"qa-6","q":"What happens after launch?","a":"We stay. Most clients keep us on for a few months of measuring, learning and iterating — and 72% come back for the next thing."}]}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_about_roles', 'about.roles', 'About: open roles', 'published', '{"label":"Careers","title":"Open <em>roles</em>","items":[{"title":"Senior Product Designer","meta":"Lisbon or remote · Full-time","subject":"Senior Product Designer"},{"title":"Design Engineer (Webflow / Next.js)","meta":"Remote · Full-time","subject":"Design Engineer"},{"title":"Brand Designer","meta":"Lisbon · Full-time","subject":"Brand Designer"},{"title":"Don''t see your role? Write to us anyway","meta":"Open application","subject":"Open application"}]}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_about_hero', 'about.hero', 'About: hero', 'published', '{"label":"About Visuolab","title":"Design that carries <em>one idea</em> from sketch to launch.","lead":"Fourteen designers, strategists and design engineers across four continents. No account managers, no hand-offs — the people you meet on the first call do the work.","facts":["Founded 2017","14 people, one team","Lisbon & remote","140+ launches"]}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
