INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_site_cta', 'site.cta', 'Closing call-to-action band', 'published', '{"title":"Ready to discuss your <em>project</em> with us?","lead":"Tell us where you are and where you want to be. We''ll come back within a day with how we''d get you there.","actions":[{"label":"Book a call","href":"mailto:hello@visuolab.studio"},{"label":"hello@visuolab.studio","href":"mailto:hello@visuolab.studio"}],"floaters":["/assets/cases/orbit.webp","/assets/cases/kite.webp","/assets/cases/marlow.webp","/assets/cases/verdant.webp"],"avatars":["/assets/people/jordan.webp","/assets/people/team-2.webp","/assets/people/aiko.webp"]}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
INSERT INTO site_settings (id, key, title, status, value_json, created_at, updated_at, updated_by) VALUES ('set_site_contact', 'site.contact', 'Contact details', 'published', '{"email":"hello@visuolab.studio","label":"Contact","title":"Tell us where you are and where you want to <em>be</em>","whoAnswers":{"name":"Jordan Ellis","role":"Founder & Creative Director — answers new enquiries","avatar":"/assets/people/jordan.webp"},"direct":[{"label":"Email","text":"hello@visuolab.studio","href":"mailto:hello@visuolab.studio"},{"label":"New business","text":"Book a 30-min intro call","href":"mailto:hello@visuolab.studio?subject=New%20project"}],"facts":["Answer within 1 working day","Lisbon & remote — 4 continents","Projects from €20k"]}', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z', NULL);
